ALTER TABLE public.tenants ADD COLUMN reference_data jsonb NOT NULL DEFAULT '{"inventory":[],"recipes":[],"shelf_life":[]}'::jsonb; CREATE OR REPLACE FUNCTION public.tenant_config(p_slug text) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT jsonb_build_object('id',slug,'name',name,'logo_url',logo_url,'primary_color',primary_color,'reference_data',reference_data) FROM public.tenants WHERE slug=p_slug AND active; $$; insert into storage.buckets(id,name,public) values('employee-docs','employee-docs',false) on conflict do nothing; CREATE POLICY tenant_documents ON storage.objects FOR ALL TO authenticated USING (bucket_id='employee-docs' AND EXISTS(SELECT 1 FROM public.tenants t JOIN public.tenant_memberships m ON m.tenant_id=t.id WHERE t.slug=(storage.foldername(name))[1] AND m.user_id=auth.uid() AND (m.role='HQ' OR m.store_id::text=(storage.foldername(name))[2]))) WITH CHECK (bucket_id='employee-docs' AND EXISTS(SELECT 1 FROM public.tenants t JOIN public.tenant_memberships m ON m.tenant_id=t.id WHERE t.slug=(storage.foldername(name))[1] AND m.user_id=auth.uid() AND (m.role='HQ' OR m.store_id::text=(storage.foldername(name))[2])));
